#!/usr/bin/env python3
"""Focused render contracts; no site files are generated by these tests."""
import tempfile
import unittest
from pathlib import Path

from registry_ui import INDEX, detail_page


class RegistryUIContracts(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory()
        self.root = Path(self.temp.name)
        self.job = {
            'id': 'canva-example', 'title': 'Research Scientist', 'organization': 'Canva',
            'record_type': 'vacancy', 'vacancy_status': 'closed',
            'country': 'Australia', 'city': 'Sydney',
            'locations': [{'country': 'United Kingdom', 'city': 'London'}, {'country': 'Australia', 'city': 'Sydney'}],
            'seniority_level': 'Principal',
            'research_direction_fit': {'level': 'high', 'label': '方向较强', 'reason': 'DIRECTION_EVIDENCE'},
            'level_fit': {'level': 'low', 'label': '职级跨度', 'reason': 'LEVEL_EVIDENCE'},
            'application_action': {'category': 'stretch', 'label': '低优先级冲刺'},
            'key_gaps': ['LEADERSHIP_GAP'],
        }

    def tearDown(self):
        self.temp.cleanup()

    def test_view_and_filter_contracts(self):
        for identifier in ('canva-view-button', 'canva-summary', 'filter-country', 'filter-city', 'filter-seniority', 'filter-researchfit', 'filter-levelfit', 'filter-action'):
            self.assertIn(f'id="{identifier}"', INDEX)
        self.assertIn('data-view="shortlist"', INDEX)
        self.assertIn('data-view="canva"', INDEX)
        self.assertIn('assets/registry.js', INDEX)
        self.assertNotIn('src="/assets/', INDEX)

    def test_direction_and_level_are_separate_detail_rows(self):
        page = detail_page(self.root, self.job, {}, False)
        for value in ('DIRECTION_EVIDENCE', 'LEVEL_EVIDENCE', 'LEADERSHIP_GAP', '方向、职级与申请决策', 'London'):
            self.assertIn(value, page)
        self.assertIn('../index.html', page)

    def test_unpublished_draft_never_gets_download_anchor(self):
        (self.root / 'draft.txt').write_text('Private draft')
        self.job.update(draft_material_status='local_draft_not_published', draft_material_note='仅本地待审', artifacts=[{'path': 'draft.txt', 'status': 'draft', 'type': 'resume'}])
        page = detail_page(self.root, self.job, {}, False)
        self.assertIn('仅本地待审', page)
        self.assertNotIn('href="../draft.txt"', page)
        self.assertNotIn(' download>', page)

    def test_submitted_record_is_not_called_wholly_unsent(self):
        self.job['application_stage'] = 'applied'
        page = detail_page(self.root, self.job, {}, False)
        self.assertIn('已有用户确认的投递', page)
        self.assertNotIn('申请文本均为草稿，未发送或提交', page)

    def test_public_safe_detail_omits_private_fit_evidence(self):
        page = detail_page(self.root, self.job, {}, True)
        for value in ('DIRECTION_EVIDENCE', 'LEVEL_EVIDENCE', 'LEADERSHIP_GAP'):
            self.assertNotIn(value, page)


if __name__ == '__main__':
    unittest.main(verbosity=2)
